    29	        while self.pos < self.input.len() {
    30	            let op = self.input.as_bytes()[self.pos] as char;
    31	            if op == '+' || op == '-' {
    32	                self.pos += 1;
    33	                let right = self.parse_number()?;
    34	                left = Expr::Binary(Box::new(left), op, Box::new(right));
    35	            } else {
    36	                break;
    37	            }
    38	        }
    39	        Ok(left)
    40	    }
