    15	impl ShiftReduceParser {
    16	    pub fn parse(tokens: &[String]) -> Result<AstNode, String> {
    17	        let mut values: Vec<AstNode> = Vec::new();
    18	        let mut ops: Vec<char> = Vec::new();
    19	
    20	        for tok in tokens {
    21	            if let Ok(num) = tok.parse::<i64>() {
    22	                values.push(AstNode::Val(num));
    23	            } else if tok == "+" || tok == "-" {
    24	                ops.push(tok.chars().next().unwrap());
    25	            }
    26	        }
    27	
    28	        while let Some(op) = ops.pop() {
    29	            if values.len() < 2 {
    30	                return Err("Malformed token sequence".to_string());
    31	            }
